from pathlib import Path
import re
p=Path('dashboard.html')
s=p.read_text()
marker='/* BARISTAMATCH CREATIVE CARD DASHBOARD */'
css=r'''
/* BARISTAMATCH CREATIVE CARD DASHBOARD */
@keyframes bmLoad{0%{transform:translateX(-100%)}100%{transform:translateX(320%)}}
.loading{position:fixed;z-index:9999;top:0;left:0;right:0;height:3px;padding:0;background:#eadfd5;color:transparent;display:block;overflow:hidden;text-align:left}
.loading:after{content:"";position:absolute;inset:0 auto 0 0;width:34%;background:linear-gradient(90deg,#7f3d16,#d9762d,#f6b16a);animation:bmLoad 1.1s ease-in-out infinite}
.loading p,.loading .loading-actions{display:none}
.loading.bm-error{inset:0;height:auto;display:grid;place-items:center;padding:24px;background:var(--cream);color:var(--muted);text-align:center}
.loading.bm-error:after{display:none}.loading.bm-error p,.loading.bm-error .loading-actions{display:block}
.role-cafe_owner_manager .shell{grid-template-columns:260px minmax(0,1fr);background:#fffaf5}
.role-cafe_owner_manager .side{background:linear-gradient(180deg,#fffaf5,#fbf3eb);color:#2d160b;border-right:1px solid #eadfd6;box-shadow:none;padding:26px 18px}
.role-cafe_owner_manager .brand{border-bottom:0;margin:0 10px 30px;padding:0;color:#2d160b;font-size:24px}.role-cafe_owner_manager .brand img{background:transparent;box-shadow:none;padding:0}.role-cafe_owner_manager .brand b{color:#b95b23}
.role-cafe_owner_manager .menu{gap:8px}.role-cafe_owner_manager .menu button{display:flex;align-items:center;gap:10px;color:#4b3428;background:#fff;border:1px solid #eee2d8;border-radius:16px;padding:13px 15px;font-weight:700;box-shadow:0 5px 14px #32170808;transition:.18s ease}
.role-cafe_owner_manager .menu button:hover{background:#fff7ef;color:#6c2e10;transform:translateY(-1px);border-color:#e3cdbd}.role-cafe_owner_manager .menu button.active{background:linear-gradient(135deg,#4b210d,#8d431a);color:#fff;border-color:transparent;box-shadow:0 12px 28px #57240e28}
.role-cafe_owner_manager .sidefoot{border-top:0}.role-cafe_owner_manager .sidefoot small,.role-cafe_owner_manager .sidefoot .logout{display:none}
.role-cafe_owner_manager .top{display:none}.role-cafe_owner_manager .content{max-width:1500px;padding:28px 34px 38px}
.cafe-wow{position:relative}.cafe-wow-head{position:relative;min-height:160px;padding:20px 280px 18px 8px;overflow:hidden}.cafe-wow-head:after{content:"☕";position:absolute;right:25px;top:-25px;font-size:170px;filter:drop-shadow(0 22px 28px #5b2b151e);transform:rotate(-8deg);opacity:.96}.cafe-wow-head:before{content:"";position:absolute;right:145px;top:45px;width:230px;height:130px;background:radial-gradient(circle at 30% 40%,#5c2d16 0 4px,transparent 5px),radial-gradient(circle at 70% 65%,#8c4a24 0 5px,transparent 6px),radial-gradient(circle at 45% 85%,#6b351a 0 3px,transparent 4px);opacity:.5}.cafe-wow-greeting{font-size:16px;color:#7a5f50;margin-bottom:6px}.cafe-wow h2{font-family:Arial,sans-serif;font-size:clamp(38px,5vw,62px);line-height:1.02;margin:0;color:#160f0b;letter-spacing:-.04em}.cafe-wow h2 em{font-family:Georgia,serif;font-weight:500;color:#d55d13}.cafe-wow-sub{margin:10px 0 0;color:#6d5d53;font-size:17px}.cafe-identity{position:absolute;right:24px;top:8px;z-index:2;display:flex;align-items:center;gap:12px;background:#fff;border:1px solid #eee1d7;border-radius:20px;padding:10px 13px;box-shadow:0 12px 32px #32170810}.cafe-identity-avatar{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:#5b260f;color:#fff;font-weight:900}.cafe-identity strong,.cafe-identity small{display:block}.cafe-identity small{color:#88766b;margin-top:3px}.wow-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin:0 0 22px}.wow-stat{min-height:190px;border-radius:22px;padding:22px;background:linear-gradient(160deg,#fff,#fff8f2);border:1px solid #eee0d5;box-shadow:0 15px 38px #3217080c;position:relative;overflow:hidden}.wow-stat:nth-child(2){background:linear-gradient(160deg,#fff,#fff4ee)}.wow-stat:nth-child(3){background:linear-gradient(160deg,#fff,#fff1f4)}.wow-stat:nth-child(4){background:linear-gradient(160deg,#291507,#3e1e0c);color:#fff;border-color:#3e1e0c}.wow-stat-label{font-size:14px;color:#6d5d53}.wow-stat:nth-child(4) .wow-stat-label{color:#dbcbbc}.wow-stat strong{display:block;font-size:44px;line-height:1;margin-top:18px}.wow-stat-trend{display:block;margin-top:10px;color:#23904f;font-weight:800;font-size:13px}.wow-chart{position:absolute;left:22px;right:22px;bottom:20px;height:38px;display:flex;align-items:end;gap:7px}.wow-chart i{display:block;flex:1;border-radius:5px 5px 2px 2px;background:#f2ba70;min-height:8px}.wow-stat:nth-child(2) .wow-chart i{background:#ff8a50}.wow-stat:nth-child(3) .wow-chart i{background:#f79ab2}.wow-stat:nth-child(4) .wow-chart{align-items:center}.wow-stat:nth-child(4) .wow-chart:before{content:"";width:100%;height:34px;border-bottom:3px solid #ef6b16;border-radius:50%;transform:skewX(-18deg)}.wow-main-grid{display:grid;grid-template-columns:1.05fr 1fr;gap:20px}.wow-cta{min-height:330px;border-radius:22px;padding:30px;position:relative;overflow:hidden;color:#fff;background:radial-gradient(circle at 80% 20%,#8a4b25 0 5%,transparent 6%),linear-gradient(135deg,#21130c 0%,#3a1e0f 52%,#7a3d1d 100%);box-shadow:0 20px 46px #3217081e}.wow-cta:after{content:"☕";position:absolute;right:5%;bottom:-22px;font-size:155px;opacity:.88;filter:drop-shadow(0 16px 20px #0005)}.wow-cta h3{font-size:28px;margin:0 0 12px}.wow-cta p{max-width:390px;color:#eadfd6;font-size:16px;line-height:1.55}.wow-cta .wow-link{position:absolute;left:30px;bottom:30px;z-index:2;border:0;background:transparent;color:#ffad6e;font-weight:900;font-size:16px;padding:0}.wow-activity{border-radius:22px;background:#fff;border:1px solid #eee0d5;padding:26px;box-shadow:0 15px 38px #3217080c}.wow-activity-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.wow-activity h3{font-size:25px;margin:0}.wow-activity-row{display:grid;grid-template-columns:42px 1fr auto;gap:12px;align-items:center;padding:17px 0;border-top:1px solid #f0e7df}.wow-activity-row:first-of-type{border-top:0}.wow-dot{width:42px;height:42px;border-radius:14px;display:grid;place-items:center;background:#fff2e7}.wow-activity-row b{display:block}.wow-activity-row small{display:block;color:#86766c;margin-top:3px}.wow-time{color:#927f73;font-size:12px;white-space:nowrap}.wow-empty{color:#7f6e63;line-height:1.55;padding:28px 4px}.wow-post{margin-top:20px;border-radius:22px;background:#fff;border:1px solid #eee0d5;padding:22px;box-shadow:0 15px 38px #3217080c}.wow-post-head{display:flex;align-items:center;justify-content:space-between}.wow-post h3{margin:0;font-size:22px}.wow-job-row{display:grid;grid-template-columns:1fr auto;gap:12px;padding:14px 0;border-top:1px solid #f0e7df}.wow-job-row:first-of-type{margin-top:8px}.wow-job-row small{display:block;color:#827167;margin-top:3px}.wow-status{align-self:center;padding:6px 9px;border-radius:99px;background:#e7f4ea;color:#287443;font-size:11px;font-weight:800}
@media(max-width:1050px){.wow-stats{grid-template-columns:repeat(2,1fr)}.wow-main-grid{grid-template-columns:1fr}.cafe-wow-head{padding-right:220px}.cafe-identity{right:0}.cafe-wow-head:after{font-size:135px}}
@media(max-width:760px){.role-cafe_owner_manager .shell{display:block}.role-cafe_owner_manager .side{position:relative;height:auto;padding:18px 14px 12px;border-right:0;border-bottom:1px solid #eadfd6}.role-cafe_owner_manager .brand{margin:0 4px 14px}.role-cafe_owner_manager .menu{display:flex;overflow:auto;gap:8px;padding-bottom:4px}.role-cafe_owner_manager .menu button{flex:0 0 auto;padding:10px 13px;border-radius:999px}.role-cafe_owner_manager .content{padding:20px 15px 100px}.cafe-wow-head{min-height:auto;padding:10px 0 110px}.cafe-wow-head:after{font-size:115px;right:2px;top:88px}.cafe-identity{top:78px;left:0;right:auto}.cafe-wow h2{font-size:38px}.wow-stats{grid-template-columns:1fr 1fr;gap:12px}.wow-stat{min-height:155px;padding:18px}.wow-stat strong{font-size:36px}.wow-main-grid{gap:14px}.wow-cta{min-height:280px}.wow-activity{padding:20px}}
@media(max-width:480px){.wow-stats{grid-template-columns:1fr}.wow-stat{min-height:145px}.wow-chart{height:28px}.cafe-wow-head{padding-bottom:118px}.cafe-wow h2{font-size:34px}.wow-activity-row{grid-template-columns:38px 1fr}.wow-time{grid-column:2}.wow-cta{padding:24px}.wow-cta .wow-link{left:24px}}
'''
if marker not in s:
    s=s.replace('</style>',css+'\n</style>',1)

# Ensure role-scoped styling can activate.
old="const role=session.user.user_metadata?.role==='cafe_owner_manager'?'cafe_owner_manager':'barista';const view=views[role];"
new="const role=session.user.user_metadata?.role==='cafe_owner_manager'?'cafe_owner_manager':'barista';document.getElementById('app').classList.add('role-'+role);const view=views[role];"
if old in s:s=s.replace(old,new,1)

# Make startup failures readable while routine startup is only a thin progress bar.
s=s.replace("function showStartupError(message){document.getElementById('loading-message').textContent=message;document.getElementById('loading-actions').hidden=false}","function showStartupError(message){const loading=document.getElementById('loading');loading.classList.add('bm-error');document.getElementById('loading-message').textContent=message;document.getElementById('loading-actions').hidden=false}")

# Replace overview renderer with approved creative card layout for cafe accounts while preserving the barista dashboard.
pattern=r"function overviewHtml\(view\)\{.*?return html\}"
replacement=r'''function overviewHtml(view){const score=profileStrength(),name=escapeHtml(profileName()),matches=applications.filter(app=>app.status==='matched').length;let html=view.html.replace(/35%/g,score+'%');if(currentRole==='barista'){html=html.replace('<h2>Welcome back</h2>',`<h2>Welcome${name==='Your barista profile'?'':`, ${name}`}</h2>`);html=html.replace('<button class="primary">Complete your profile</button>',`<button class="primary" data-edit-profile>${score===100?'Edit your profile':'Complete your profile'}</button>`).replace('<span>Open jobs</span><strong>0</strong>',`<span>Open jobs</span><strong>${marketJobs.length}</strong>`).replace('<span>Matches</span><strong>0</strong>',`<span>Matches</span><strong>${matches}</strong>`).replace('<span>Applications</span><strong>0</strong>',`<span>Applications</span><strong>${applications.length}</strong>`);return html}
const activeJobs=marketJobs.filter(job=>job.active).length,newCandidates=applications.filter(app=>app.status==='interested').length,cafeName=name==='Your café'?'Your café':name,location=escapeHtml(currentProfile.location||'Location not added'),jobs=marketJobs.slice(0,4),recent=applications.slice(0,3);
const chart=(heights,color='')=>`<div class="wow-chart">${heights.map(h=>`<i style="height:${h}%${color?`;background:${color}`:''}"></i>`).join('')}</div>`;
const activity=recent.length?recent.map(app=>{const candidate=escapeHtml(app.barista?.display_name||'A barista'),title=escapeHtml(app.job?.title||'your job'),label=app.status==='matched'?`You matched with ${candidate}`:`${candidate} showed interest in ${title}`,icon=app.status==='matched'?'♡':'☕',when=new Date(app.created_at).toLocaleDateString([], {month:'short',day:'numeric'});return `<div class="wow-activity-row"><span class="wow-dot">${icon}</span><div><b>${label}</b><small>${title}</small></div><span class="wow-time">${escapeHtml(when)}</span></div>`}).join(''):`<div class="wow-empty">Your hiring activity will appear here as baristas discover your jobs, match, and message you.</div>`;
const jobRows=jobs.length?jobs.map(job=>`<div class="wow-job-row"><div><b>${escapeHtml(job.title||'Café role')}</b><small>${escapeHtml(job.location||location)} · ${escapeHtml(job.schedule||'Schedule not added')}</small></div><span class="wow-status">${job.active?'Active':'Closed'}</span></div>`).join(''):`<div class="wow-empty">No job posts yet. Create your first role to start meeting baristas.</div>`;
return `<section class="cafe-wow"><div class="cafe-wow-head"><div class="cafe-wow-greeting">Welcome back,</div><h2>${cafeName}</h2><p class="cafe-wow-sub">Here's your hiring overview.</p><div class="cafe-identity"><span class="cafe-identity-avatar">${escapeHtml((cafeName||'C').slice(0,2).toUpperCase())}</span><div><strong>${cafeName}</strong><small>${location}</small></div></div></div><div class="wow-stats"><article class="wow-stat"><span class="wow-stat-label">Active Jobs</span><strong>${activeJobs}</strong><span class="wow-stat-trend">Live now</span>${chart([24,38,22,55,42,66,48,82])}</article><article class="wow-stat"><span class="wow-stat-label">New Candidates</span><strong>${newCandidates}</strong><span class="wow-stat-trend">Ready to review</span>${chart([18,44,16,35,76,40,62,48])}</article><article class="wow-stat"><span class="wow-stat-label">Matches</span><strong>${matches}</strong><span class="wow-stat-trend">Connections</span>${chart([22,35,18,58,55,49,79,28])}</article><article class="wow-stat"><span class="wow-stat-label">Total Jobs</span><strong>${marketJobs.length}</strong><span class="wow-stat-trend">All time</span><div class="wow-chart"></div></article></div><div class="wow-main-grid"><article class="wow-cta"><h3>Post a job in minutes</h3><p>Reach baristas near you and start getting quality applicants without the job-board noise.</p><button class="wow-link" data-go="Job Posts">Create job post →</button></article><article class="wow-activity"><div class="wow-activity-head"><h3>Recent activity</h3><button class="secondary" data-go="Candidates">View all</button></div>${activity}</article></div><article class="wow-post"><div class="wow-post-head"><h3>Recent job posts</h3><button class="secondary" data-go="Job Posts">View all jobs →</button></div>${jobRows}</article></section>`}'''
s2,n=re.subn(pattern,replacement,s,count=1,flags=re.S)
if n!=1:raise SystemExit('Could not replace overviewHtml renderer')
s=s2

# Keep the in-dashboard subscription summary aligned with current pricing.
old_price="function pricingSubscriptionHtml(){return `<div class=\"section-intro\"><p>Simple, transparent pricing for your café.</p></div><div class=\"pricing-panel\"><article class=\"pricing-offer\"><span class=\"pricing-kicker\">Your first 30 days are on us</span><div class=\"pricing-price\">$24.99 <small>/ month after your free trial</small></div><p class=\"empty\">Use BaristaMatch free for 30 days. After that, continue for just $24.99/month.</p>"
if old_price in s:
    s=s.replace(old_price,"function pricingSubscriptionHtml(){return `<div class=\"section-intro\"><p>Simple, transparent pricing for your café.</p></div><div class=\"pricing-panel\"><article class=\"pricing-offer\"><span class=\"pricing-kicker\">30 days free · no card required</span><div class=\"pricing-price\">$24.99 <small>/ month</small></div><p class=\"empty\">Choose monthly for $24.99 or yearly for $239.99 after your free trial.</p>",1)

p.write_text(s)
print('dashboard redesign applied')
